    "titulo": "How Do Sounds on Mars Differ from Sounds on Earth? ",
    "descripcion": "Did you know sound works differently on Mars than it does on Earth? Mars has a different atmosphere than Earth, so sounds on the Red Planet would sound a bit different and be more muffled. NASA’s Mars Perseverance rover has two microphones that record sounds on the Red Planet. Since its landing in February 2021, the rover has captured sounds such as dust devils, the whir of the Ingenuity Mars Helicopter in flight, and the sound of its wheels crunching over the rocky Martian terrain.   Learn more about Perseverance: https://mars.nasa.gov/mars2020  For more sounds of Mars: http://mars.nasa.gov/m",
    "fecha": "2023-05-16",
    "centro": "JPL",
