    "titulo": "Nasa’s Mars Ingenuity Helicopter Test Flight Campaign",
    "descripcion": "B-roll for media use. NASA's Ingenuity Mars Helicopter arrived on the Red Planet attached to the belly of the agency's Perseverance rover, which touched down on Feb. 18, 2021.   The small rotorcraft made history on April 19, 2021, hovering above Jezero Crater, demonstrating that powered, controlled flight on another planet is possible. Subsequent flights were even bolder and more ambitious than previous flight attempts.    The helicopter is flying with Perseverance and even lending the rover a helping hand. Ingenuity’s ninth flight provided imagery that will help the Perseverance rover team de",
