    "titulo": "JPL-20200429-TECHf-0001-Mars Helicopter Media Reel 04272020",
    "descripcion": "B-roll for media. NASA's Mars Helicopter Ingenuity will be the first aircraft to fly in a controlled way on another planet. It will fly to Mars attached to the belly of NASA’s Perseverance rover, part of the Mars 2020 mission.  In April, the Mars helicopter was given the name Ingenuity. This reel includes a conversation between the student whose name was chosen -- Vaneeza Rupani, 17, of Northport, Alabama -- and MiMi Aung, the Mars helicopter project manager based at NASA's Jet Propulsion Laboratory.   The Ingenuity helicopter is considered a high-risk, high-reward technology demonstration. If",
