    "tipo": "video",
    "titulo": "Mars Helicopter Prepares for Takeoff",
    "descripcion": "Beginning April 2021, the window opens for the first flight of NASA’s Ingenuity Mars Helicopter.  It will be history’s first attempt at powered, controlled flight on another planet.  Ingenuity arrived at Mars on February 18, 2021, riding along with NASA’s Perseverance rover.  Before it attempts takeoff, the Mars Helicopter must first survive the arduous journey to Mars – from the turbulent liftoff to the harrowing landing – as well as dangerously cold nights where it must maintain power to keep itself warm enough to operate. The duration of Ingenuity’s mission is 30 days, where one or more tes",
