    "titulo": "NASA Ingenuity Mars Helicopter Testing Media Reel",
    "descripcion": "B-roll for media. NASA's Ingenuity Mars Helicopter will make history's first attempt at powered, controlled flight on another planet next spring. Before the project was approved by NASA to ride with the agency's next mission to Mars (the Mars 2020 Perseverance rover), the Mars Helicopter team had to prove powered flight in a Martian atmosphere was possible.   This video highlights three important milestones in the flight-testing program of the Mars helicopter system. The testing took place in the 25-foot space simulation chamber at NASA's Jet Propulsion Laboratory in Southern California where ",
