    "tipo": "video",
    "titulo": "The Most Extreme Flights of NASA’s Ingenuity Mars Helicopter (Mars Report)",
    "descripcion": "NASA’s Ingenuity Mars Helicopter pushed aerodynamic limits during the final months of its mission, setting new records for speed, distance, and altitude. Hear from Ingenuity chief engineer Travis Brown on how the data the team collected could eventually be used in future rotorcraft designs.   Ingenuity was originally designed to make up to five flights – but completed 72 before sustaining rotor-blade damage that rendered it unable to fly. NASA announced the end of the helicopter’s mission on Jan. 25, 2024. NASA’s Jet Propulsion Laboratory in Southern California built and manages operations for",
