    "nasa_id": "JPL-20230607-MARSf-0001-Mars Report Whats in A Name",
    "tipo": "video",
    "titulo": "How Does NASA Name Things on Mars? (Mars Report - June 2023)",
    "descripcion": "NASA’s Perseverance and Curiosity rovers are exploring new terrain on Mars every day, adding thousands of names to the Red Planet over the last few years. Set in the Perseverance rover operations area at NASA’s Jet Propulsion Laboratory, this edition of the Mars Report features geologist Tina Seeger of Caltech explaining the process for naming Mars rocks, drill targets, and other locations as the teams explore.  This video discusses how official and unofficial names are decided by scientists who need a common language to reference while navigating Mars. For the Curiosity and Perseverance missi",
    "fecha": "2023-06-07",
    "centro": "JPL",
    "url": "https://images-assets.nasa.gov/video/JPL-20230607-MARSf-0001-Mars Report Whats in A Name/JPL-20230607-MARSf-0001-Mars Report Whats in A Name~thumb.jpg",
