    "descripcion": "B-roll for media. NASA's Mars 2020 mission, which includes the Perseverance rover, is launching to the Red Planet in July or August 2020. It will land on Mars February 18, 2021. Much of this footage was shot in 2019 as the spacecraft was being assembled at NASA's Jet Propulsion Laboratory in Southern California..  NASA’s Mars 2020 rover will search for signs of past microbial life, characterize the planet's climate and geology and collect samples for future return to Earth. Mars 2020 is also part of a larger program that includes missions to the Moon as a way to prepare for human exploration o",
