    "tipo": "video",
    "titulo": "Earth to Mars: How NASA Keeps Curiosity Connected (Mars Report) ",
    "descripcion": "NASA’s Curiosity rover is exploring a scientifically exciting area on Mars, but communicating with the mission team on Earth has recently been a challenge due to both the current season and the surrounding terrain. In this Mars Report, Curiosity engineer Reidar Larsen takes you inside the uplink room where the team talks to the rover. See why Curiosity’s location in Gediz Vallis channel makes it difficult to send direct commands — and how the team ensures they always stay connected to the rover.  Curiosity landed in 2012 to look for evidence that Mars’ Gale Crater had the conditions to support",
