    "tipo": "video",
    "titulo": "Getting NASA’s Perseverance Mars Rover to Launch During the COVID-19 Pandemic",
    "descripcion": "Getting a Mars rover built, tested and to the launch pad is a feat that requires the dedication of hundreds of team members. The team behind NASA’s Perseverance Mars rover faced one of its biggest challenges when the coronavirus pandemic struck during a crucial time before launch. The safety of the team members became top priority yet they rose to the challenge of completing the rover on time for its launch date, either by working remotely or under new “safe at work” procedures. They developed an increased appreciation for the name of the rover and in May they created the COVID-19 Perseverance",
    "fecha": "2020-06-17",
    "centro": "JPL",
