    "titulo": "Orion_Artemis-I_animation_b-roll_9_2021_FS",
    "descripcion": "Animation showing Orion's journey to the Moon on Artemis I - full screen version.  Artemis I will be the first integrated flight test of NASA’s deep space exploration system: the Orion spacecraft, Space Launch System (SLS) rocket and the ground systems at Kennedy Space Center in Cape Canaveral, Florida. During this flight, the uncrewed Orion spacecraft will launch on the most powerful rocket in the world and travel thousands of miles beyond the Moon, farther than any spacecraft built for humans has ever flown, over the course of about a three-week mission.",
