    "tipo": "video",
    "titulo": "International Observe the Moon Night - Sept. 26 2020",
    "descripcion": "On September 26, 2020, Moon enthusiasts and curious people worldwide will come together to celebrate International Observe the Moon Night. Everyone on Earth is invited to learn about lunar science and exploration, take part in celestial observations, and honor cultural and personal connections to the Moon. International Observe the Moon Night occurs annually in September or October, when the Moon is around first quarter ― a great phase for evening observing.   You can join International Observe the Moon Night from wherever you are. Attend or host a virtual or in-person event, or observe the Mo",
