    "tipo": "video",
    "titulo": "NASA Explores the Moon and Beyond",
    "descripcion": "NASA continues to forge ahead in humanity’s quest for knowledge as we explore the Moon and Mars. Through Artemis, we will expand our robotic and human exploration of the Moon and land the first woman and the first person of color on the lunar surface. As we get ready to venture beyond, the technology we develop and discoveries we make on the Moon will prepare us for Mars and our next giant leap: sending humans to the Red Planet. Learn more atnasa.gov/moontomars",
    "fecha": "2022-03-28",
