    "titulo": "#AskNASA┃ How Will Astronauts Dig on the Moon",
    "descripcion": "How will we uncover the history of the Moon? What tools and instruments will help us dig deeper? The latest episode of #AskNASA will answer these questions and more.  NASA’s Chief Exploration Scientist Jacob Bleacher demonstrates exactly how craters help us understand the history of Moon rocks and the Moon’s surface.  As part of the Artemis program, Jacob highlights the import role astronauts play in finding and analyzing samples. Jacob also explains how field work on Earth support both science and human exploration.",
