    "tipo": "video",
    "titulo": "10 Years at the Moon",
    "descripcion": "NASA’s Lunar Reconnaissance Orbiter mission now celebrates its 10-year anniversary of being at the Moon. After launching on June 18, 2009 and entering lunar orbit on June 23rd, the spacecraft continues to collect vast amounts of data vital to our understanding of the lunar landscape and environment, our solar system, and to our future exploration goals for the Moon and Mars. This video highlights some notable facts and accomplishments of the LRO mission over the past decade, all of which are paving the way forward for reestablishing a human presence on the Moon with the newly-announced Artemis",
    "fecha": "2019-06-18",
    "centro": "GSFC",
