    "nasa_id": "ARC-20200610-AAV3276-VIPER-CLPSAnnounce-RptrPkg-NASAWeb-1080p",
    "tipo": "video",
    "titulo": "NASA Moon Rover Books Ride to the Moon",
    "descripcion": "NASA’s water-seeking robotic Moon rover just booked a ride to the Moon’s South Pole. Astrobotic of Pittsburgh, Pennsylvania, has been selected to deliver the Volatiles Investigating Polar Exploration Rover, or VIPER, to the Moon in 2023. During its 100-Earth-day mission, the approximately 1,000-pound rover will roam several miles and use its four science instruments to sample various soil environments in search of water ice. Its survey will help pave the way for a new era of human missions to the lunar surface and will bring us a step closer to developing a sustainable, long-term robotic and h",
