    "tipo": "video",
    "titulo": "#AskNASA I Why Can't We Just Land on the Moon?",
    "descripcion": "NASA is working with its partners to design and develop a small spaceship that will orbit the Moon called the Gateway. This spaceship will be a temporary home and office for astronauts, just about a five-day, 250,000-mile commute from Earth.    NASA’s Gateway Program Logistics Element Manager Mark Weiss answers questions about the Gateway’s development’s for the Artemis Missions.   The first logistics service to the orbital outpost is expected to deliver science, cargo and other supplies in support of the agency’s new Artemis lunar exploration program, which includes sending the first woman an",
