    "titulo": "LRO's Diviner Takes the Moon's Temperature During Eclipse: Moon View",
    "descripcion": "During the June 2011 lunar eclipse, scientists will be able to get a unique view of the moon. While the sun is blocked by the Earth, LRO's Diviner instrument will take the temperature on the lunar surface. Since different rock sizes cool at different rates, scientists will be able to infer the size and density of rocks on the moon.",
