    "nasa_id": "GSFC_20130603_LEND_m11292_Water",
    "tipo": "video",
    "titulo": "Water on the Moon",
    "descripcion": "Since the 1960’s, scientists have suspected that frozen water could survive in cold, dark craters at the Moon’s poles. While previous lunar missions have detected hints of water on the Moon, new data from the Lunar Reconnaissance Orbiter (LRO) pinpoints areas near the south pole where water is likely to exist. The key to this discovery is hydrogen, the main ingredient in water: LRO uses its Lunar Exploration Neutron Detector, or LEND, to measure how much hydrogen is trapped within the lunar soil. By combining years of LEND data, scientists see mounting evidence of hydrogen-rich areas near the ",
    "fecha": "2013-06-03",
    "centro": "GSFC",
    "url": "https://images-assets.nasa.gov/video/GSFC_20130603_LEND_m11292_Water/GSFC_20130603_LEND_m11292_Water~thumb.jpg",
    "url_video": "https://images-assets.nasa.gov/video/GSFC_20130603_LEND_m11292_Water/GSFC_20130603_LEND_m11292_Water~orig.mp4",
