    "nasa_id": "GSFC_20120220_LRO_m10915_ graben_moon",
    "tipo": "video",
    "titulo": "NASA Spacecraft Reveals Recent Geological Activity on the Moon",
    "descripcion": "New images acquired by NASA's Lunar Reconnaissance Orbiter (LRO) spacecraft show that the moon's crust is being slightly stretched, forming small valleys - at least in some small areas. High-resolution images obtained by the Lunar Reconnaissance Orbiter Camera (LROC) provide evidence that these valleys are very young, suggesting the moon has experienced relatively recent geologic activity.",
