    "nasa_id": "GSFC_20170721_LRO_m12648_SolarEclipse",
    "tipo": "video",
    "titulo": "The Moon's Role in a Solar Eclipse",
    "descripcion": "While the sun is the main focus of a solar eclipse, our moon plays the most crucial role in creating this unique event. This video tutorial explains what happens during a total solar eclipse and a partial eclipse and how often they both occur. The video also explains how a solar eclipse differs from a lunar eclipse, and gives a helpful tip on how to remember the difference. In addition, the video examines how the two parts of the moon’s shadow, the umbra and penumbra, affect how we see an eclipse on the Earth, and illustrates the surprising true shape of the umbra. The video concludes by highl",
    "fecha": "2017-07-21",
    "centro": "GSFC",
    "url": "https://images-assets.nasa.gov/video/GSFC_20170721_LRO_m12648_SolarEclipse/GSFC_20170721_LRO_m12648_SolarEclipse~thumb.jpg",
    "url_video": "https://images-assets.nasa.gov/video/GSFC_20170721_LRO_m12648_SolarEclipse/GSFC_20170721_LRO_m12648_SolarEclipse~orig.mp4",
