    "tipo": "video",
    "titulo": "NASA Moon Base: The First Six Months",
    "descripcion": "No aim is too high. No journey is too far. No challenge is too tough.   Since NASA announced plans for a Moon Base in March 2026, work has been moving quickly to turn an ambitious vision into reality. From identifying commercial partners to sending humans around the Moon for the first time in decades, we are advancing the missions, technologies, and capabilities that will help build humanity’s first lunar outpost.  We’re going back to the Moon. This time, to stay.   Learn more about the Moon Base: https://nasa.gov/moonbase   Credit: NASA",
