    "tipo": "video",
    "titulo": "Hubble and Going Forward to the Moon",
    "descripcion": "We are going forward to the Moon by 2024, but did you know that back in 2005, Dr. Jim Garvin and his team of scientists pointed the Hubble Space Telescope at our nearest celestial neighbor for a very important reason?   The Hubble team used the telescope’s powerful instruments to work as a prospector for the Moon’s surface, searching for resources that would help future human-led missions mine and utilize those materials to “live off the land” of the Moon.   Hubble’s lunar research led the way for future missions, such as the Lunar Reconnaissance Orbiter, helping men and women to go forward to",
