    "descripcion": "How long does it take to get to the Moon? Mars? Jupiter? The answer is: it depends — and speed is only one factor. Travel times also depend on distance, fuel, physics and clever trajectory planning. From quick trips to the Moon to years-long voyages to the outer planets, every mission follows a unique path. Watch as a NASA scientist breaks down what it really takes to travel through space.   Learn more about how we navigate the solar system: https://science.nasa.gov/learn/basics...  Link to download this video: coming soon   Producers: Scott Bednar, Pedro Cota, Jessica Wilde Editor: James Luca",
