    "descripcion": "NASA announced the three American companies selected to build 21st century human landing systems (HLS) for Artemis missions to the Moon. This announcement keeps America on track to land the first woman and the next man on the lunar surface by 2024.   The three companies selected are:  ·        Blue Origin of Kent, Washington ·        Dynetics of Huntsville, Alabama ·        SpaceX of Hawthorne, California  This exciting final step in our acquisition process puts all the pieces in play needed to explore the Moon quickly and sustainably. Working more efficiently with our commercial partners than",
