    "descripcion": "As you watch the Moon over the course of a month, you'll notice that different features are illuminated by the Sun at different times. However, there are some parts of the Moon that never see sunlight. These areas are called permanently shadowed regions, and they appear dark because unlike on the Earth, the axis of the Moon is nearly perpendicular to the direction of the sun's light. The result is that the bottoms of certain craters are never pointed toward the Sun, with some remaining dark for over two billion years. However, thanks to new data from NASA's Lunar Reconnaissance Orbiter, we can",
    "fecha": "2013-03-06",
    "centro": "GSFC",
    "url": "https://images-assets.nasa.gov/video/GSFC_20130306_Moons_m11218_Shadowed/GSFC_20130306_Moons_m11218_Shadowed~thumb.jpg",
    "url_video": "https://images-assets.nasa.gov/video/GSFC_20130306_Moons_m11218_Shadowed/GSFC_20130306_Moons_m11218_Shadowed~orig.mp4",
    "imagen_local": "biblioteca/img/moon/GSFC_20130306_Moons_m11218_Shadowed.jpg"
