    "tipo": "video",
    "titulo": "New Supercomputer Simulation Sheds Light on Moon’s Origin",
    "descripcion": "A new NASA and Durham University simulation puts forth a different theory of the Moon’s origin – the Moon may have formed in a matter of hours, when material from the Earth and a Mars sized-body were launched directly into orbit after the impact. The simulations used in this research are some of the most detailed of their kind, operating at the highest resolution of any simulation run to study the Moon’s origins or other giant impacts.  For more information, please visit https://www.nasa.gov/feature/ames/lunar-origins-simulations",
    "fecha": "2022-10-04",
    "centro": "ARC",
    "url": "https://images-assets.nasa.gov/video/ARC-20221004-AAV3443-MoonOrigin-Social-NASAWeb-1080p/ARC-20221004-AAV3443-MoonOrigin-Social-NASAWeb-1080p~thumb.jpg",
