    "tipo": "video",
    "titulo": "Earth Views from the International Space Station",
    "descripcion": "The International Space Station’s High Definition Earth Viewing (HDEV) experiment is an external camera platform located on the Columbus module of the space station. In addition to providing beautiful views of Earth, one of the goals of HDEV is to monitor the longevity and quality of its image sensors in the space environment. HDEV operations began April 30, 2014 and only a single bad pixel has been identified.",
