    "tipo": "video",
    "titulo": "NASA's Vantage Point to View Earth",
    "descripcion": "No planet is better studied than the one we actually live on. NASA's fleet of 26 Earth science spacecraft, supported by aircraft, ships and ground observations, measure aspects of the environment that touch the lives of every person around the world. They study everything from the air we breathe, to rain and snow that provide water for agriculture and communities, to natural disasters such as droughts and floods, to the oceans, which cover 70 percent of Earth’s surface and provide food for many people around the world. Satellites and instruments on the International Space Station circle the wh",
    "fecha": "2017-04-19",
