    "tipo": "video",
    "titulo": "Best of \"Earth As Art\" - Top Five",
    "descripcion": "A series of Landsat satellites have surveyed the Earth's surface since 1972. In that time, Landsat data have become a vital reference worldwide, used for understanding scientific issues related to land use and natural resources. However, some Landsat images are simply striking to look at - presenting spectacular views of mountains and valleys, forests and farms. To celebrate the 40th anniversary of Landsat, the US Geological Survey and NASA asked for your help in selecting the top five Earth As Art images.",
