    "tipo": "video",
    "titulo": "Earth Day Media Briefing: NASA Unveils New Elements of Climate Research",
    "descripcion": "Earth Day Media Briefing NASA Unveils New Elements of Climate Research  In anticipation of Earth Day, NASA invited media to a briefing at the agency’s headquarters on Friday, April 19. The event shared updates on NASA’s climate science and early data from the agency’s ocean-watching PACE (Plankton, Aerosol, Cloud, ocean Ecosystem) mission, and revealed upcoming Earth airborne missions.  The speakers included: NASA Administrator Bill Nelson Karen St. Germain, division director, NASA Earth Sciences Division Tom Wagner, associate director for Earth Action",
