    "tipo": "video",
    "titulo": "OUR ALIEN EARTH: The Undersea Volcanoes of Santorini, Greece",
    "descripcion": "Dive alongside Dr. Richard Camilli and his team as they explore the undersea volcanoes off of the coast of Santorini, Greece. Testing a suite of autonomous underwater vehicles, the team hopes to imbue their robotic explorers with the same scientific reasoning of a human astrobiologist, helping us characterize alien oceans and remotely search for signs of life on distant ocean worlds.",
