    "nasa_id": "JPL-20221111-EARTHf-0001-Earth Water Budget Animation",
    "tipo": "video",
    "titulo": "Earth Water Budget Animation",
    "descripcion": "Earth’s 370 quintillion gallons of water can be found all over the planet in lakes, rivers, glaciers, oceans, and groundwater. However, only a tiny fraction of this water is usable by humans. Understanding Earth’s ‘water budget’ – where these different forms of water exist and how they move – is an important part of understanding our planet and planning for future water needs. NASA has a fleet of satellites to help us bring Earth’s water budget into focus, including upcoming missions like SWOT (Surface Water and Ocean Topography).  SWOT is scheduled to launch from Vandenberg Space Force Base i",
    "fecha": "2022-12-09",
    "centro": "JPL",
    "url": "https://images-assets.nasa.gov/video/JPL-20221111-EARTHf-0001-Earth Water Budget Animation/JPL-20221111-EARTHf-0001-Earth Water Budget Animation~thumb.jpg",
