    "descripcion": "NASA’s human spaceflight missions have steadily built on each other, leading us to a continuous human presence in low Earth orbit for 23 years. Now, as we stand on the cusp of a new era of human spaceflight, NASA is calling for feedback on what the agency’s goals and objectives should be for the low Earth orbit microgravity environment. The agency will utilize future commercial space stations to advance microgravity science, technology, and exploration.",
