    "descripcion": "This year at NASA, Earth Day is about connections—to our planet and to each other. Our planet is home to over 7 billion people of diverse backgrounds and experiences, but we are all #ConnectedByEarth. Join NASA climate experts to learn about the connections between human activity and climate change. Tag your questions using #askNASA to have your questions answered live during our Earth Day episode of #NASAScience Live on #EarthDay: Thursday, April 22. --Dr. Kimberley R. Miner, Climate Scientist, Host, NASA JPL-- Dr. Lesley Ott, Climate Scientist, NASA Goddard-- Equisha Glenn, Graduate Student ",
