    "tipo": "video",
    "titulo": "EPIC Observations Pouring In: NASA at the 2015 AGU Fall Meeting",
    "descripcion": "Less than a year after its launch on the Deep Space Climate Observatory (DSCOVR), NASA’s onboard camera is taking images of the entire sunlit side of Earth every two hours.  From its vantage point balanced between the sun and Earth, the Earth Polychromatic Imaging Camera (EPIC) provides a new view on our home planet – able to see the daily cycle of clouds and ozone, and the swirls of thick aerosols like dust as they move across oceans and continents. Because the DSCOVR satellite is always between the sun and Earth, EPIC also provides a new view for studying vegetation by naturally separating s",
    "fecha": "2015-12-14",
