    "nasa_id": "GSFC_20170816_ICESat2_m12663_Elevates",
    "tipo": "video",
    "titulo": "ICESat-2 Elevates Our View of Earth",
    "descripcion": "ICESat-2 will provide scientists with height measurements that create a global portrait of Earth’s third dimension, gathering data that can precisely track changes of terrain including glaciers, sea ice, forests and more. The single instrument on ICESat-2 is ATLAS, the Advanced Topographic Laser Altimeter System, will measure melting ice sheets and investigate how this effects sea level rise, investigate changes in the mass of ice sheets and glaciers, estimate and study sea ice thickness, and measure the height of vegetation in forests and other ecosystems worldwide.",
