    "tipo": "video",
    "titulo": "How to View and Share Your Planet with Worldview",
    "descripcion": "NASA’s Worldview app lets you explore Earth as it looks right now or as it looked almost 20 years ago. Through an easy-to-use map interface, you can watch tropical storms developing over the Pacific Ocean; track the movement of icebergs after they calve from glaciers and ice shelves; see wildfires spread and grow as they burn vegetation in its path. Pan-and-zoom to your region of the world to see not only what it looks like today, but to investigate changes over time. Worldview's nighttime lights layers provides a truly unique perspective of our planet at night.  What else can you do with Worl",
