    "tipo": "video",
    "titulo": "NISAR: Tracking Earth’s Changes From Space (Mission Overview)",
    "descripcion": "NASA and ISRO (Indian Space Research Organisation) have teamed up to create a powerful new space mission that will track our changing Earth in fine detail. The satellite, called NISAR, will use an advanced radar system to deepen our understanding of deforestation, shrinking glaciers and sea ice loss, natural hazards, climate change, and other global vital signs.  Short for NASA-ISRO Synthetic Aperture Radar, NISAR features two radar instruments: one from ISRO, and one built at NASA’s Jet Propulsion Laboratory in Southern California. Peering through cloud cover and vegetation, the satellite wil",
