    "nasa_id": "GSFC_20121018_Gradient_m11112_Sun.en",
    "tipo": "video",
    "titulo": "Gradient Sun",
    "descripcion": "Watching a particularly beautiful movie of the sun helps show how the lines between science and art can sometimes blur. But there is more to the connection between the two disciplines: science and art techniques are often quite similar, indeed one may inform the other or be improved based on lessons from the other arena. One such case is a technique known as a \"gradient filter\" — recognizable to many people as an option available on a photo-editing program. Gradients are, in fact, a mathematical description that highlights the places of greatest physical change in space. A gradient filter, in ",
    "fecha": "2012-10-18",
    "centro": "GSFC",
    "url": "https://images-assets.nasa.gov/video/GSFC_20121018_Gradient_m11112_Sun.en/GSFC_20121018_Gradient_m11112_Sun.en~thumb.jpg",
