    "nasa_id": "GSFC_20180808_Parker_m13017_SolarProbe",
    "tipo": "video",
    "titulo": "It's Surprisingly Hard to Go to the Sun",
    "descripcion": "The Sun contains 99.8 percent of the mass in our solar system. Its gravitational pull is what keeps everything here, from tiny Mercury to the gas giants to the Oort Cloud, 186 billion miles away. But even though the Sun has such a powerful pull, it's surprisingly hard to actually go to the Sun: It takes 55 times more energy to go to the Sun than it does to go to Mars.   Why is it so difficult? The answer lies in the same fact that keeps Earth from plunging into the Sun: Our planet is traveling very fast — about 67,000 miles per hour — almost entirely sideways relative to the Sun. The only way ",
    "fecha": "2018-08-08",
    "centro": "GSFC",
    "url": "https://images-assets.nasa.gov/video/GSFC_20180808_Parker_m13017_SolarProbe/GSFC_20180808_Parker_m13017_SolarProbe~thumb.jpg",
    "url_video": "https://images-assets.nasa.gov/video/GSFC_20180808_Parker_m13017_SolarProbe/GSFC_20180808_Parker_m13017_SolarProbe~orig.mp4",
