    "nasa_id": "GSFC_20160901_STEREO_m12329_SolarWind",
    "tipo": "video",
    "titulo": "Snapshots from the Edge of the Sun",
    "descripcion": "For the first time, using NASA’s Solar Terrestrial Relations Observatory, or STEREO, scientists have imaged the edge of the sun and described that transition – from which the solar wind blows. Defining the details of this boundary helps us learn more about our solar neighborhood, which is bathed throughout by solar material – a space environment that we must understand to safely explore beyond our planet. A paper on the findings was published in The Astrophysical Journal on Sept. 1, 2016.",
    "fecha": "2016-09-01",
    "centro": "GSFC",
    "url": "https://images-assets.nasa.gov/video/GSFC_20160901_STEREO_m12329_SolarWind/GSFC_20160901_STEREO_m12329_SolarWind~thumb.jpg",
