    "nasa_id": "GSFC_20180725_Parker_m12903_CoronalHeating_Short",
    "tipo": "video",
    "titulo": "The Sun’s Mysteriously Hot Atmosphere",
    "descripcion": "Something mysterious is going on at the Sun. In defiance of all logic, its atmosphere gets much, much hotter the farther it stretches from the Sun’s blazing surface.  Temperatures in the corona — the tenuous, outermost layer of the solar atmosphere — spike upwards of 2 million degrees Fahrenheit, while just 1,000 miles below, the underlying surface simmers at a balmy 10,000 F. How the Sun manages this feat remains one of the greatest unanswered questions in astrophysics; scientists call it the coronal heating problem. A new, landmark mission, NASA’s Parker Solar Probe — scheduled to launch no ",
    "fecha": "2018-07-25",
    "centro": "GSFC",
    "url": "https://images-assets.nasa.gov/video/GSFC_20180725_Parker_m12903_CoronalHeating_Short/GSFC_20180725_Parker_m12903_CoronalHeating_Short~thumb.jpg",
