    "nasa_id": "NHQ_2020_0106_AskNASA",
    "tipo": "video",
    "titulo": "#AskNASA┃Is the Sun a ball of fire?",
    "descripcion": "Is the Sun a ball of fire? And why does NASA send missions to the Sun? NASA’s Heliophysics Director Nicky Fox explains NASA’s latest solar science findings. The Parker Solar Probe mission is revolutionizing our understanding of the Sun, where changing conditions can propagate out into the solar system, affecting Earth and other worlds. It will travel through the Sun’s atmosphere, closer to the surface than any spacecraft before it, facing brutal heat and radiation conditions — and ultimately providing humanity with the closest-ever observations of a star.",
