    "tipo": "imagen",
    "titulo": "Three-Telescope View of the Sun",
    "descripcion": "This composite image of the Sun includes high-energy X-ray data from NASA's Nuclear Spectroscopic Telescope Array (NuSTAR) shown in blue; lower energy X-ray data from the X-ray Telescope (XRT) on the Japanese Aerospace Exploration Agency's Hinode mission shown in green; and ultraviolet light detected by the Atmospheric Imaging Assembly (AIA) on NASA's Solar Dynamics Observatory (SDO) shown in red.  NuSTAR's relatively small field of view means it can't see the entire Sun from its position in Earth orbit, so Figure A is a composite of 25 images, which were taken by the observatory in June 2022.",
