    "tipo": "video",
    "titulo": "Holiday Lights on the Sun",
    "descripcion": "The sun emitted a significant solar flare, peaking at 7:24 p.m. EST on Dec. 19, 2014. NASA’s Solar Dynamics Observatory, which watches the sun constantly, captured an image of the event. Solar flares are powerful bursts of radiation. Harmful radiation from a flare cannot pass through Earth's atmosphere to physically affect humans on the ground, however -- when intense enough -- they can disturb the atmosphere in the layer where GPS and communications signals travel.  To see how this event may affect Earth, please visit NOAA's Space Weather Prediction Center at http://spaceweather.gov, the U.S.",
