    "nasa_id": "PIA21461",
    "tipo": "imagen",
    "titulo": "Earth Eclipses the Sun",
    "descripcion": "Several times a day for a few days the Earth completely blocked the Sun for about an hour due to NASA's Solar Dynamics Observatory's orbital path (Feb. 15, 2017). The edge of the Earth is not crisp, but kind of fuzzy due to Earth's atmosphere. This frame from a video shows the ending of one such eclipse over -- just seven minutes. The sun is shown in a wavelength of extreme ultraviolet light. These eclipses re-occur about every six months. The Moon blocks SDO's view of the sun on occasion as well.  Movies are available at http://photojournal.jpl.nasa.gov/catalog/PIA21461",
    "fecha": "2017-02-21",
