    "nasa_id": "GSFC_20170330_Rossby_m12550_Waves",
    "tipo": "video",
    "titulo": "Rossby Waves on the Sun Could Aid in Space Weather Prediction",
    "descripcion": "To predict weather on a planet, we look at Rossby waves, large movement patterns in the atmosphere, like the jet stream. Just as on Earth, the conditions on the sun are constantly changing. This is why scientists were excited to discover Rossby waves on the sun.   On the sun, the waves are driven by magnetic currents below the surface. Monitoring these waves and the disturbances they generate could help us make better long-term space weather predictions.  Solar Rossby wave imagery of courtsey of Scott W. McIntosh, NCAR/HAO",
    "fecha": "2017-03-30",
    "centro": "GSFC",
