    "titulo": "Active Region on the Sun Emits Another Flare",
    "descripcion": "The sun emitted a significant solar flare on Oct. 22, 2012, peaking at 11:17 p.m. EDT. The flare came from an active region on the left side of the sun that has been numbered AR 1598, which has already been the source of a number of weaker flares. This flare was classified as an X.1-class flare. \"X-class\" denotes the most intense flares, while the number provides more information about its strength. An X2 is twice as intense as an X1, an X3 is three times as intense, and on. An X-class flare of this intensity can cause degradation or blackouts of radio communications for about an hour.  Solar ",
