    "titulo": "Comet Plunge and CME on the Sun",
    "descripcion": "A small comet was streaking towards the Sun when the Sun blew out a &quot;halo&quot; coronal mass ejection (CME) Aug. 19-20, 2013). The CME originated from the far side of the Sun and did not have any interaction with the comet. The comet, only perhaps 30 meters across, was not seen after it went out of view, likely disintegrated by the heat and radiation from the Sun. We call this a &quot;full halo&quot; CME since the front edge of the CME is expanding in all directions around the Sun like a halo.  The images were taken by SOHO's coronagraphs in which a disk (red) blocks the Sun and some of t",
