    "titulo": "From the Sun with Love",
    "descripcion": "This Solar Dynamics Observatory (SDO) image of the Sun taken on January 20, 2012 in extreme ultraviolet light captures a heart-shaped dark coronal hole. Coronal holes are areas of the Sun's surface that are the source of open magnetic field lines that head way out into space. They are also the source regions of the fast solar wind, which is characterized by a relatively steady speed of approximately 800 km/s (about 1.8 million mph).   <b><a href=\"http://www.nasa.gov/audience/formedia/features/MP_Photo_Guidelines.html\" rel=\"nofollow\">NASA image use policy.</a></b>  <b><a href=\"http://www.nasa.g",
