    "tipo": "imagen",
    "titulo": "Comet Jacques Approaches the Sun",
    "descripcion": "NASA's Solar TErrestrial Relations Observatory, STEREO has observed the recently discovered Comet Jacques as it passed by its nearest approach to the Sun (July 1-6, 2014). The wide field instrument on board STEREO (Ahead) showed the comet with its elongated tail being stretched and pummeled by the gusty solar wind streaming from the Sun. Also visible near the center of the image is the bright planet Venus. The Sun is just out of the field of view to the right. Comet Jacques is traveling through space at about 180,000 km per hour (110,000 mph). It may brighten enough to be seen with the naked e",
