    "tipo": "imagen",
    "titulo": "Comet ISON Approaching the Sun [still]",
    "descripcion": "This movie from NASA’s STEREO spacecraft's Heliospheric Imager shows Comet ISON, Mercury, Comet Encke and Earth over a five-day period from Nov. 20 to Nov. 25, 2013. The sun sits right of the field of view of this camera. Comet ISON, which will round the sun on Nov. 28, is what's known as a sungrazing comet, due to its close approach.  Foreshortening or the angle at which these images were obtained make Earth appear as if it is closer to the sun than Mercury. If you look closely you will also see a dimmer and smaller comet Encke near comet ISON.   A comet’s journey through the solar system is ",
