    "nasa_id": "GSFC_20180822_Parker_m13046_Sunset_Show",
    "tipo": "video",
    "titulo": "Sunset Show for Parker Solar Probe",
    "descripcion": "Early in the morning of Aug. 12, NASA launched Parker Solar Probe, humanity’s first mission to the Sun. This spacecraft will fly closer to the Sun than any before it, in a daring journey facing brutal heat and radiation.   Parker Solar Probe sets its sights on the Sun’s scorching outer atmosphere, called the corona, in order to solve our star’s greatest mysteries. It will revolutionize our understanding not only of the Sun, but also the space around us, and even the lives of stars beyond our solar system — crucial information as we explore more of space.  On Aug. 10, scientists and mission exp",
    "fecha": "2018-08-22",
    "centro": "GSFC",
    "url": "https://images-assets.nasa.gov/video/GSFC_20180822_Parker_m13046_Sunset_Show/GSFC_20180822_Parker_m13046_Sunset_Show~thumb.jpg",
