    "tipo": "imagen",
    "titulo": "Solar Scientist Confirm Existence of Flux Ropes on the Sun",
    "descripcion": "Caption: This is an image of magnetic loops on the sun, captured by NASA's Solar Dynamics Observatory (SDO).  It has been processed to highlight the edges of each loop to make the structure more clear.  A series of loops such as this is known as a flux rope, and these lie at the heart of eruptions on the sun known as coronal mass ejections (CMEs.) This is the first time scientists were able to discern the timing of a flux rope's formation.  (SDO AIA 131 and 171 difference blended image of flux ropes during CME.)  Credit: NASA/Goddard Space Flight Center/SDO  ----  On July 18, 2012, a fairly sm",
