    "nasa_id": "GSFC_20160129_Dynamic_m12104_Magnetic",
    "tipo": "video",
    "titulo": "The Dynamic Solar Magnetic Field - Narrated",
    "descripcion": "In this video NASA solar physicist Holly Gilbert narrates a visualization of the slow changes in the sun's magnetic field over the course of four years.  Grasping what drives that magnetic system is crucial for understanding the nature of space throughout the solar system: The sun's invisible magnetic field is responsible for everything from the solar explosions that cause space weather on Earth – such as auroras – to the interplanetary magnetic field and radiation through which our spacecraft journeying around the solar system must travel.   We can observe the shape of the magnetic fields abo",
    "fecha": "2016-01-29",
    "centro": "GSFC",
    "url": "https://images-assets.nasa.gov/video/GSFC_20160129_Dynamic_m12104_Magnetic/GSFC_20160129_Dynamic_m12104_Magnetic~thumb.jpg",
