    "nasa_id": "GSFC_20170621_Eclipse_m12551_Promo",
    "tipo": "video",
    "titulo": "Get Ready for the 2017 Solar Eclipse",
    "descripcion": "On Monday, August 21, 2017, our nation will be treated to a total eclipse of the sun. The eclipse will be visible -- weather permitting -- across all of North America. The whole continent will experience a partial eclipse lasting two to three hours. Halfway through the event, anyone within a 60 to 70 mile-wide path from Oregon to South Carolina will experience a total eclipse. During those brief moments when the moon completely blocks the sun’s bright face for 2 + minutes, day will turn into night, making visible the otherwise hidden solar corona, the sun’s outer atmosphere. Bright stars and p",
    "fecha": "2017-06-21",
