    "titulo": "Atmospheric Motion in Jupiter Northern Hemisphere",
    "descripcion": "True-color (left) and false-color (right) mosaics of Jupiter's northern hemisphere between 10 and 50 degrees latitude. Jupiter's atmospheric motions are controlled by alternating eastward and westward bands of air between Jupiter's equator and polar regions. The direction and speed of these bands influences the color and texture of the clouds seen in this mosaic. The high and thin clouds are represented by light blue, deep clouds are reddish, and high and thick clouds are white. A high haze overlying a clear, deep atmosphere is represented by dark purple. This image was taken by NASA's Galileo",
