    "tipo": "imagen",
    "titulo": "Time Series of Jupiter Aurora",
    "descripcion": "These mosaics of Jupiter's night side show the Jovian aurora at approximately 45 minute intervals as the auroral ring rotated with the planet below the spacecraft. The images were obtained by the Solid State Imaging (SSI) system on NASA's Galileo spacecraft. during its eleventh orbit of Jupiter.  The auroral ring is offset from Jupiter's pole of rotation and reaches the lowest latitude near 165 degrees west longitude. The aurora is hundreds of kilometers wide, and when it crosses the edge of Jupiter, it is about 250 kilometers above the planet.  As on Earth, the auroral emission is caused by e",
