    "tipo": "imagen",
    "titulo": "A Hot Spot on Jupiter",
    "descripcion": "This composite image shows a hot spot in Jupiter's atmosphere. In the image on the left, taken on Sept. 16, 2020, by the Gemini North telescope on the island of Hawaii, the hot spot appears bright in the infrared at a wavelength of 5 microns. In the inset image on the right, taken by Juno's JunoCam visible-light imager, also on Sept. 16 during Juno's 29th perijove pass, the hot spot appears dark.  Scientists have known of Jupiter's hot spots for a long time. On Dec. 7, 1995, the Galileo probe likely descended into a similar hot spot. To the naked eye, Jupiter's hot spots appear as dark, cloud-",
