    "nasa_id": "hubble-captures-vivid-auroras-in-jupiters-atmosphere_28000029525_o",
    "tipo": "imagen",
    "titulo": "Hubble Captures Vivid Auroras in Jupiter’s Atmosphere",
    "descripcion": "Astronomers are using the NASA/ESA Hubble Space Telescope to study auroras — stunning light shows in a planet’s atmosphere — on the poles of the largest planet in the solar system, Jupiter. This observation program is supported by measurements made by NASA’s Juno spacecraft, currently on its way to Jupiter.  Jupiter, the largest planet in the solar system, is best known for its colorful storms, the most famous being the Great Red Spot. Now astronomers have focused on another beautiful feature of the planet, using Hubble's ultraviolet capabilities.  The extraordinary vivid glows shown in the ne",
    "fecha": "2016-06-30",
    "centro": "GSFC",
    "url": "https://images-assets.nasa.gov/image/hubble-captures-vivid-auroras-in-jupiters-atmosphere_28000029525_o/hubble-captures-vivid-auroras-in-jupiters-atmosphere_28000029525_o~thumb.jpg",
