    "descripcion": "This view of Jupiter Great Red Spot is a mosaic of two images taken by NASA Galileo spacecraft. The Great Red Spot is a storm in Jupiter atmosphere and is at least 300 years-old. The image was taken on June 26, 1996.  http://photojournal.jpl.nasa.gov/catalog/PIA00296",
