    "titulo": "NASA Science Live: Galaxy of Horrors [Episode 10]",
    "descripcion": "So it is Halloween, the day of the dead. And to celebrate this chilling holiday, we are taking you on a tour of our galaxy of horrors. First, we’re going to start at the far reaches of the Milky Way Galaxy and explore terrifying planets that orbit other stars. (roll-ins for this) Then, we'll come a bit closer to home by exploring some of the most eerie environments in our own solar system. Have you ever heard radio waves from Saturn? You will today. Then, we will dive into the dark forces at play in our universe: Dark energy and dark matter.  For higher resolution file for download, go to: htt",
