    "tipo": "imagen",
    "titulo": "Hubble’s Hidden Galaxy",
    "descripcion": "IC 342 is a challenging cosmic target. Although it is bright, the galaxy sits near the equator of the Milky Way’s galactic disk, where the sky is thick with glowing cosmic gas, bright stars, and dark, obscuring dust. In order for astronomers to see the intricate spiral structure of IC 342, they must gaze through a large amount of material contained within our own galaxy — no easy feat! As a result IC 342 is relatively difficult to spot and image, giving rise to its intriguing nickname: the “Hidden Galaxy.”  Located very close (in astronomical terms) to the Milky Way, this sweeping spiral galax",
