    "titulo": "NASA's Hubble Spots Embryonic Galaxy SPT0615-JD",
    "descripcion": "This Hubble Space Telescope image shows the farthest galaxy yet seen in an image that has been stretched and amplified by a phenomenon called gravitational lensing. The embryonic galaxy, named SPT0615-JD, existed when the universe was just 500 million years old. Though a few other primitive galaxies have been seen at this early epoch, they have essentially all looked like red dots, given their small size and tremendous distances. However, in this case, the gravitational field of a massive foreground galaxy cluster, called SPT-CL J0615-5746, not only amplified the light from the background gala",
