    "tipo": "imagen",
    "titulo": "Lonely Galaxy Lost in Space",
    "descripcion": "Most galaxies are clumped together in groups or clusters. A neighboring galaxy is never far away. But this galaxy, known as NGC 6503, has found itself in a lonely position, at the edge of a strangely empty patch of space called the Local Void.  The Local Void is a huge stretch of space that is at least 150 million light-years across. It seems completely empty of stars or galaxies. The galaxy’s odd location on the edge of this never-land led stargazer Stephen James O’Meara to dub it the “Lost-In-Space galaxy” in his 2007 book, Hidden Treasures.  NGC 6503 is 18 million light-years away from us i",
