    "titulo": "Hubble Spots a Secluded Starburst Galaxy",
    "descripcion": "This image was taken by the NASA/ESA Hubble Space Telescope’s Advanced Camera for Surveys (ACS) and shows a starburst galaxy named MCG+07-33-027. This galaxy lies some 300 million light-years away from us, and is currently experiencing an extraordinarily high rate of star formation — a starburst.   Normal galaxies produce only a couple of new stars per year, but starburst galaxies can produce a hundred times more than that. As MCG+07-33-027 is seen face-on, the galaxy’s spiral arms and the bright star-forming regions within them are clearly visible and easy for astronomers to study.  In order ",
