    "nasa_id": "GSFC_20171208_Archive_e000033",
    "tipo": "imagen",
    "titulo": "Hubble Captures Massive Dead Disk Galaxy that Challenges Theories of Galaxy Evolution",
    "descripcion": "By combining the power of a &quot;natural lens&quot; in space with the capability of NASA's Hubble Space Telescope, astronomers made a surprising discovery—the first example of a compact yet massive, fast-spinning, disk-shaped galaxy that stopped making stars only a few billion years after the big bang.  Finding such a galaxy early in the history of the universe challenges the current understanding of how massive galaxies form and evolve, say researchers.  Read more: <a href=\"https://go.nasa.gov/2sWwKkc\" rel=\"nofollow\">go.nasa.gov/2sWwKkc</a>  caption: Acting as a “natural telescope” in space,",
    "fecha": "2017-12-08",
