    "titulo": "Training Montage – Astronaut Group 23 ",
    "descripcion": "From spacewalk training in NASA’s Neutral Buoyancy Laboratory to studying space station systems, to flying in a T-38 jet or trekking through the wilderness, NASA’s astronaut training program allows astronaut candidates to work through problems and build relationships with their classmates to ready them for future space flights to the International Space Station, future orbiting destinations, the Moon, and beyond.",
    "fecha": "2024-03-08",
    "centro": "JSC",
    "url": "https://images-assets.nasa.gov/video/jsc2024m000081_Training Montage – Astronaut Group 23_HighQuality MP4/jsc2024m000081_Training Montage – Astronaut Group 23_HighQuality MP4~thumb.jpg",
    "url_video": "https://images-assets.nasa.gov/video/jsc2024m000081_Training Montage – Astronaut Group 23_HighQuality MP4/jsc2024m000081_Training Montage – Astronaut Group 23_HighQuality MP4~orig.mp4"
