    "nasa_id": "NHQ_2020_0302_AskNASA - How can I be an Astronaut",
    "tipo": "video",
    "titulo": "#AskNASA - How Can I Be An Astronaut?",
    "descripcion": "As NASA prepares to launch American astronauts this year on American rockets from American soil to the International Space Station – with an eye toward the Moon and Mars – NASA is accepting applications March 2 to 31 for the next class of Artemis Generation astronauts. The basic requirements to apply include United States citizenship and a master’s degree in a STEM field, including engineering, biological science, physical science, computer science, or mathematics, from an accredited institution. Candidates also must have at least two years of related, progressively responsible professional ex",
