    "tipo": "video",
    "titulo": "What Do Astronauts Eat In Space?",
    "descripcion": "While working and living aboard the International Space Station, astronauts need nutritious meals to keep them healthy, focused, and energized. But what do they eat in space? Learn about their out-of-this-world food and how NASA is focused on creating meals and snacks that will sustain crews during future missions to the Moon and Mars.",
