    "titulo": "Wreath Laying Ceremony for Astronaut Owen Garriott",
    "descripcion": "NASA is remembering the accomplishments of Skylab and Space Shuttle astronaut Owen Garriott, who died April 15 at the age of 88. A wreath laying ceremony honoring Garriott was held on April 18 at the Heroes and Legends exhibit featuring the Astronaut Hall of Fame at the Kennedy Space Center Visitor Complex in Florida. Garriott was selected as a NASA astronaut in June 1965. He flew aboard the Skylab space station during the Skylab 3 mission and on the space shuttle Columbia for the STS-9/Spacelab-1 mission.",
