    "nasa_id": "NHQ_2024_0305_The Universe is Calling Apply to Be a NASA Astronaut",
    "tipo": "video",
    "titulo": "The Universe is Calling Apply to Be a NASA Astronaut",
    "descripcion": "We’re recruiting for our next class of NASA astronauts. Selected candidates could fly on Artemis missions to the Moon and, eventually, Mars. Will you be one of them?  Applications are open from March 5 through April 2, 2024. Read the requirements and start your application by visiting https://go.nasa.gov/astro2024.  Don't think you have what it takes? There's no such thing as a typical astronaut. We’re seeking out team players, passionate people, candidates who thrive under pressure and excel in what they do. The universe is calling. Explore with us.  Video Producer: Daniel Lauchu Executive Pr",
    "fecha": "2024-03-05",
