    "tipo": "video",
    "titulo": "Astronauts Share Tips for Viewing a Total Solar Eclipse",
    "descripcion": "Astronauts Stephen Bowen, Woody Hoburg, Frank Rubio and Sultan Alneyadi are on a mission to get you ready for the upcoming total eclipse on Monday, April 8, 2024.  Not in the path of the eclipse? Watch with us from anywhere in the world. We will provide live broadcast coverage from 1 to 4 p.m. EDT (1700 to 2000 UTC) on April 8. We’ll share conversations with experts and provide telescope views of the eclipse from several sites along the eclipse path: https://www.youtube.com/watchv=2MJY_ptQW1o  WARNING: Except during the brief totality phase of a total solar eclipse, when the Moon completely bl",
