    "tipo": "video",
    "titulo": "Artemis II Launches Astronauts to the Moon (Official NASA Recap)",
    "descripcion": "Artemis II’s SLS (Space Launch System) rocket lifted off from Launch Pad 39B at NASA’s Kennedy Space Center in Florida, at 6:35 p.m. EDT (2235 UTC) on April 1, 2026, sending NASA astronauts Reid Wiseman, Victor Glover, Christina Koch, and CSA (Canadian Space Agency) astronaut Jeremy Hansen on an approximately 10-day test flight around the Moon and back aboard their Orion spacecraft.   This video includes highlights from the day of launch. Follow along as the four astronauts continue their journey around the Moon and back: https://www.nasa.gov/ways-to-watch/  Learn more at: https://www.nasa.gov",
