    "tipo": "video",
    "titulo": "#AskNASA┃ HOW DO ASTRONAUTS USE THE POTTY IN SPACE?",
    "descripcion": "Hygiene, eating, sleeping — life operates a tad differently when you're in space. Join NASA Astronaut Jessica Meir as she answers some of our popular questions about living aboard the International Space Station.   Jessica explains how the lack of gravity makes everyday activities not so ordinary, from washing your hair in zero gravity to using the bathroom in space. Jessica details how astronauts handle the tricky tasks and offer a sneak peek at the new space toilet planned for NASA's Artemis program. Celebrating her most notable achievement, Jessica shares her thoughts about her first spacew",
