    "tipo": "video",
    "titulo": "The Color of Space: A NASA Documentary Showcasing the Stories of Black Astronauts",
    "descripcion": "The Color of Space captures the personal stories of seven current and former Black astronauts, each selected to become part of NASA's astronaut corps and train for space missions. Current NASA astronauts Stephanie Wilson, Victor Glover, Jeanette Epps, as well as retired astronauts Leland Melvin, Bernard Harris, Robert Curbeam, and Bobby Satcher, speak about their journeys and their motivations in a panel hosted by NASA Johnson Space Center Director Vanessa Wyche, the first Black woman to lead a NASA center. They took the step to achieve the impossible, overcoming barriers and making space for ",
    "fecha": "2022-06-19",
    "centro": "HQ",
