    "nasa_id": "NHQ_2020_0225_Tuskegee Airman Wants YOU to Be an Astronaut",
    "tipo": "video",
    "titulo": "Tuskegee Airman Wants YOU to Be an Astronaut",
    "descripcion": "Honorary Brigadier General Charles McGee wants YOU to be an astronaut! McGee served as a pilot with the Tuskegee Airmen during World War II – known at the time as the “Red Tails” – was a career officer in the Air Force and also served during the Korean and Vietnam wars, having flown 409 combat missions during his 30 years of service. Of the 355 Tuskegee pilots who flew in combat, McGee is one of only nine surviving.   He stopped by NASA to encourage the next generation of Astronauts to fly to new heights.   For more information about a career as a NASA astronaut, and application requirements, ",
