    "titulo": "Eddie Vedder of Pearl Jam Speaks with Astronauts in Space",
    "descripcion": "Grammy-winning recording artist Eddie Vedder made a special long-distance phone call to the International Space Station (ISS), in celebration of Earth Day.  Orbiting more than 250 miles (402 kilometers) above Earth aboard the ISS, NASA astronauts Kayla Barron, Raja Chari, Thomas Marshburn, and Mark Vande Hei, as well as ESA (European Space Agency) astronaut Matthias Maurer, have enjoyed a unique view of our planet. They share their thoughts on having a front-row seat to the global effects of climate change, reflect on stewardship of our planet, as well as space’s remarkable ability to unite al",
