    "descripcion": "Dedicated to a life full of learning, NASA astronaut Jonny Kim is prepared for his first mission to the International Space Station, where he will conduct scientific investigations and technology demonstrations to help prepare for future space missions and provide benefits to people on Earth. The former Navy SEAL and emergency medicine resident will launch on the Roscosmos Soyuz MS-27 spacecraft in April 2025 along with Roscosmos cosmonauts Sergey Ryzhikov and Alexey Zubritsky, serving as a flight engineer and member of the Expedition 72/73 crew for approximately eight months. Get the latest u",
