    "titulo": "Hubble Tool Time Episode 1 - Astronaut Training",
    "descripcion": "Retired NASA astronaut John Grunsfeld hosts this six-part mini-series about the tools used on the Hubble Space Telescope servicing missions. Hubble was uniquely designed to be serviced in space so that components could be repaired and upgraded. Astronauts using custom-designed tools performed challenging spacewalks on five servicing missions from 1993 to 2009 to keep Hubble operating so that it could change our fundamental understanding of the universe.  Join John and astronaut trainer Christy Hansen in this first episode to learn about how astronauts trained to use the tools on the Hubble ser",
