    "tipo": "video",
    "titulo": "KSC-04-S-00252",
    "descripcion": "The space adventure is officially starting for eight of NASA's newest astronauts and three astronauts from the Japan Aerospace Exploration Agency. They recently launched into a six-week basic training program in Pensacola, Florida. During their first two weeks, the astronauts braved water survival training, swim tests, altitude chambers and ejection seats. For the remainder of the program, they'll concentrate on flight training. Eleven new astronaut candidates were selected for this year's astronaut class, announced in May. The eight NASA astronauts in the training program are Mission Speciali",
    "fecha": "2004-07-20",
    "centro": "KSC",
