    "titulo": "Join NASA Astronauts on Mission Equity",
    "descripcion": "NASA has issued a Request for Information (RFI) to receive input from the public on NASA’s mission directorates’ programs, procurements, grants, regulations and policies.  NASA will use this information to evaluate, implement, modify, expand, and streamline its programs, procurements, grants, regulations and policies to remove systemic inequitable barriers and challenges facing underserved communities. NASA will continue a dialogue with industry and stakeholders to stay connected and engaged on barriers and challenges that impact members of the underserved communities through a public meeting ",
