    "tipo": "video",
    "titulo": "Surprisingly STEM: Astronaut Fitness Trainer",
    "descripcion": "Get pumped to learn about Corey Twine’s journey from training athletes, to soldiers, to astronauts! Maintaining good health and fitness is critical for humans living and working in space. To keep astronauts in tip top shape during their missions, NASA has astronaut strength and conditioning coaches like Corey who train the astronauts before and after they leave Earth. It’s no stretch to say that Corey has a very cool job!",
