    "nasa_id": "jsc2025m000028_How_Do_Astronauts_Practice_Self-Care_in_Space_250331",
    "tipo": "video",
    "titulo": "How Do Astronauts Practice Self-Care in Space?",
    "descripcion": "Everyone needs a little self-care. But what’s that look like for astronauts orbiting 250 miles above Earth? See how crew members may turn to music, movies, and more to unwind and recharge.  Learn more about the ongoing research exploring human health in space at NASA’s Human Research Program: www.nasa.gov/hrp  Join NASA as we go forward to the Moon and on to Mars -- discover the latest on Earth, the Solar System and beyond with a weekly update in your inbox.  Subscribe at: https://www.nasa.gov/subscribe",
    "fecha": "2025-04-07",
    "centro": "JSC",
