    "titulo": "NASA Astronaut Jonny Kim Training Resource Reel",
    "descripcion": "NASA astronaut Jonny Kim trains for his upcoming mission to the International Space Station. It will be the first trip to space for Kim after being selected as an astronaut in 2017. He will launch on the Roscosmos Soyuz MS-27 spacecraft with Roscosmos cosmonauts Sergey Ryzhikov and Alexey Zubritsky, becoming an Expedition 72/73 flight engineer after arriving on the space station. Throughout his approximately 8 month mission, Kim and his crewmates will conduct numerous scientific experiments and technology demonstrations, and maintain the space station.  Join NASA as we go forward to the Moon a",
