    "descripcion": "NASA completed signing of the Human Rating Certification Plan for SpaceX’s crew transportation system on Tuesday, Nov. 10, 2020. The Crew Dragon, including the Falcon 9 rocket and associated ground systems, is the first new crew spacecraft to be NASA-certified for regular flights with astronauts since the space shuttle nearly 40 years ago. Several critical events paved the way for the landmark announcement, including grounds tests, simulations, uncrewed flight tests and a successful test flight with astronauts aboard.",
