    "titulo": "A Look at Webb Telescope’s Specially Designed Shipping Container",
    "descripcion": "When NASA’s James Webb Space Telescope needs to move, it must be carefully packed inside a specially designed container called the Space Telescope Transporter for Air, Road, and Sea (STTARS). As the name implies, the container protects Webb during its journeys on ground, above ground, and over water. The massive container weighs approximately 165,000 pounds (almost 75,000 kilograms) and dwarfs Webb in terms of mass — the telescope weighs approximately 14,000 pounds (6,350 kilograms) here on Earth. All of that bulk is needed to keep Webb’s individual parts, and eventually the fully assembled te",
