    "titulo": "Vibration Testing of NASA's James Webb Space Telescope",
    "descripcion": "Inside NASA's Goddard Space Flight Center in Greenbelt, Maryland the James Webb Space Telescope team completed the environmental portion of vibration testing on the telescope.  A shaker table is used to shake satellites to ensure a spacecraft like Webb can withstand the shaking that comes with a ride into space on a rocket. The new vibration test system simulates the forces the telescope will feel during the launch by vibrating it from 5 to 100 times per second. For more information about NASA's James Webb Space Telescope, visit: www.jwst.nasa.gov or www.nasa.gov/webb.",
