    "titulo": "NASA Telescopes Reveal an Invisible Infrared Universe",
    "descripcion": "For 40 years, NASA has expanded our view of the universe with space telescopes that detect infrared light, which is invisible to the human eye. Observing the infrared realm helps us study the origins of planets, stars, galaxies, and even the universe itself.   NASA’s James Webb Space Telescope is the agency’s latest infrared space telescope, adding new insights to targets first discovered and studied by infrared missions that came before it.    Infrared space telescope missions have built upon one another to reveal stars, galaxies, and all manner of cosmic objects with ever-increasing clarity.",
