    "titulo": "The Nancy Grace Roman Space Telescope Mission Trailer ",
    "descripcion": "Our newest orbiting observatory, the Nancy Grace Roman Space Telescope, is scheduled to lift off on Aug. 30. After launching, it will start its journey to its new home 1 million miles away from Earth.  Named after NASA’s first chief astronomer, the Nancy Grace Roman Space Telescope will have a deep, panoramic view of the cosmos, producing images over 100 times larger than our Hubble Space Telescope, but with the same crisp resolution. With its wide view and sophisticated host of tools, Roman will help us discover new exoplanets and untangle cosmic mysteries such as the nature of dark matter an",
