    "titulo": "James Webb Space Telescope’s Multifaceted MIRI",
    "descripcion": "James Webb Space Telescope’s mid-infrared instrument (MIRI) has both a camera and a spectrograph that sees light in the mid-infrared region of the electromagnetic spectrum, with wavelengths that are longer than our eyes see. MIRI covers the wavelength range of 5 to 28.5 microns. Its sensitive detectors will allow it to see the redshifted light of distant galaxies, helping identify the first galaxies in the universe, observe newly forming stars by peering inside dust-shrouded stellar nurseries, and analyze the atmospheres of exoplanets for markers of potential life. MIRI's camera will provide w",
