    "descripcion": "This photograph shows the Hubble Space Telescope (HST) being assembled in the clean room of the Lockheed Missile Space Company. The Optical Telescope Assembly (OTA) is being readied for the installation of the AFT shroud. The OTA contains two mirrors, primary and secondary, to collect and focus light from selected celestial objects. The HST is the first of NASA's great observatories and the most complex and sensitive optical telescope ever made. The purpose of the HST is to study the cosmos from a low-Earth orbit by placing the telescope in space, enabling astronomers to collect data that is f",
