    "titulo": "NASA Science Live: What’s Next for the James Webb Space Telescope? [Episode 41]",
    "descripcion": "The past month has been very exciting for NASA’s James Webb Space Telescope — from launch in tropical French Guiana, to the two-week unfolding of this intricately-packed telescope, the observatory has gone through a huge transformation in space. What is next for Webb as it cools down over the next 5 months and looks to #UnfoldTheUniverse? Join mission experts as they explain Webb’s journey and answer questions from the public.",
