    "nasa_id": "GSFC_20171208_Archive_e000353",
    "tipo": "imagen",
    "titulo": "Dr. John Mather and the James Webb Space Telescope",
    "descripcion": "Nobel Laureate and James Webb Space Telescope project scientist Dr. John Mather takes a selfie with the telescope. May 4, 2016 was a rare day for JWST, as it briefly faced the cleanroom observation window. The telescope was eventually rotated face-down in prep for the installation of the flight instruments.   Credit: Meredith Gibb",
